// CKNE-aware slot allocation
function calculateSlots(ckne, poolUtilization) {
  const baseSlots = 1;
  const maxSlots = poolUtilization < 0.8 ? 10 : 6;
  return Math.floor(ckne * maxSlots) + baseSlots;
}

// Cache budget calculation
function calculateCacheBudget(ckne) {
  return ckne > 0.7 ? 20 : ckne > 0.3 ? 5 : 1;
}
```

